using System.Text;using UnityEditor;using UnityEngine;using UnityEngine.UI;
public static class InspectDetailsLayout {public static string Execute(){var b=new StringBuilder();foreach(var name in new[]{"ItemDetailsPopup","CommonPopup","EquipmentSelectionPopup"}){var r=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Resources/Prefabs/Popups/"+name+".prefab");foreach(var t in r.GetComponentsInChildren<RectTransform>(true))if(t.name=="Window"||t.name=="bg"||t.GetComponent<Button>()!=null)b.AppendLine(name+" "+t.name+" parent="+t.parent?.name+" anchors="+t.anchorMin+"/"+t.anchorMax+" pivot="+t.pivot+" pos="+t.anchoredPosition+" size="+t.sizeDelta); }return b.ToString();}}
